class Solution {
    vector<int> p,sz;
    int find(int x){return p[x]==x?x:p[x]=find(p[x]);}
    void unite(int a,int b){a=find(a);b=find(b);if(a!=b){if(sz[a]<sz[b])swap(a,b);p[b]=a;sz[a]+=sz[b];}}
public:
    bool canTraverseAllPairs(vector<int>& nums) {
        int n=nums.size();if(n==1)return true;
        for(int x:nums)if(x==1)return false;
        p.resize(n);iota(p.begin(),p.end(),0);sz.assign(n,1);
        unordered_map<int,int> owner;
        for(int i=0;i<n;++i){int x=nums[i];for(int d=2;1LL*d*d<=x;++d){if(x%d)continue;if(owner.count(d))unite(i,owner[d]);else owner[d]=i;while(x%d==0)x/=d;}if(x>1){if(owner.count(x))unite(i,owner[x]);else owner[x]=i;}}
        for(int i=1;i<n;++i)if(find(i)!=find(0))return false;
        return true;
    }
};
